from functools import wraps

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            k = key(*args, **kwargs)
            if lock:
                with lock:
                    try:
                        return cache[k]
                    except KeyError:
                        value = func(*args, **kwargs)
                        cache[k] = value
                        return value
            else:
                try:
                    return cache[k]
                except KeyError:
                    value = func

